<?php
declare(strict_types=1);
/**
 * B1150 read-only application check, run as its own uncached CLI process:
 * php -d opcache.enable=0 b1150-app-check.php <active tree> features|env|media-sample <64 hex HMAC key, env only>
 * It boots the CMS console kernel exactly as artisan does, refuses a cached configuration and prints ONE JSON object with
 * booleans, counts and fixed keywords only (never a setting value, path, URL or credential; the media-sample URL is the one
 * documented exception: a signed public image URL, printed to the coordinator and never written to the report). It never
 * writes and never sends mail.
 * features: whether the NEW_CLASSES of the payload load through composer (newClassesTotal / newClassesLoaded), whether the
 * CHANGED_STATIC_APIS exist, whether the named route MEDIA_ROUTE_NAME exists with GET, and the B1149 facts that must stay in
 * both states (routes site-assets.show and admin.settings.smtp.index, MailSettingsServiceProvider registered, the POST-only
 * theme route of B1148).
 * env: PHP extensions of this CLI (dom, libxml, fileinfo, mbstring, gd, imagick), whether APP_URL is an origin the shipped
 * catalog rule accepts, and mailFingerprintHMAC: one HMAC-SHA256, keyed with a random per-run key the caller passes, over the
 * effective mail transport (default mailer, transport, host, port, encryption, timeout, hashes of username and password, from
 * address, mailer names). The caller keeps the key and the result only in its private 0600 state file and never prints either;
 * comparing the two results proves the transport did not change.
 * media-sample: the proof of the signed route without a login when the public catalog page shows no product image: ONE signed
 * URL for the first product image, generated by the application's own signer, read-only. B1150_FILL: the hook below returns
 * null until the code of codex/product-media-route-20261112 is known.
 * @author Ald1n <https://ald1n.com>
 */
$fail=static function(string $code):never{echo json_encode(['ok'=>false,'error'=>$code]).PHP_EOL;exit(2);};
[$self,$base,$mode,$key]=$argv+[null,null,null,null];
if(PHP_SAPI!=='cli'||!is_string($base)||realpath($base)!==$base||!is_file($base.'/artisan')||!in_array($mode,['features','env','media-sample'],true)||($mode==='env'&&(!is_string($key)||preg_match('/^[a-f0-9]{64}$/D',$key)!==1)))$fail('APP_CHECK_ARGUMENTS');
if(is_file($base.'/bootstrap/cache/config.php'))$fail('APP_CHECK_CONFIG_CACHED');
// B1150_FILL: classes the payload adds (fully qualified, new files only), static/instance methods it adds or changes ([class, method]),
// and the route name; the route name must equal MediaInstallCoordinator::MEDIA_ROUTE_NAME.
const NEW_CLASSES=[];
const CHANGED_APIS=[];
const MEDIA_ROUTE_NAME='B1150_FILL_ROUTE_NAME';
// The eleven classes B1149 delivered; they stay loadable in both states.
const B1149_CLASSES=['App\Services\SvgSanitizer','App\Services\SvgSanitizeResult','App\Services\SvgSanitizerException','App\Services\SiteLogoAssetService','App\Rules\SiteLogoFile','App\Services\SmtpMailSettingsService','App\Services\MailRuntimeConfigurator','App\Services\SmtpTestTransportFactory','App\Providers\MailSettingsServiceProvider','App\Support\PublicProductImageFiles','App\Support\PublicProductImages'];
if(MEDIA_ROUTE_NAME==='B1150_FILL_ROUTE_NAME')$fail('APP_CHECK_ROUTE_NAME_NOT_FILLED_IN');
try{
    chdir($base);require $base.'/vendor/autoload.php';$app=require $base.'/bootstrap/app.php';
    if(method_exists($app,'configurationIsCached')&&$app->configurationIsCached())$fail('APP_CHECK_CONFIG_CACHED');
    $app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();
    if($mode==='env'){
        $ext=[];foreach(['dom','libxml','fileinfo','mbstring','gd','imagick'] as $x)$ext[$x]=extension_loaded($x);
        $origin=class_exists(App\Support\PublicCatalogPresentation::class,true)&&App\Support\PublicCatalogPresentation::baseUrl()!==null;
        $mail=(array)config('mail');$default=(string)($mail['default']??'');$mailer=(array)(($mail['mailers']??[])[$default]??[]);
        $fingerprint=hash_hmac('sha256',json_encode(['default'=>$default,'transport'=>$mailer['transport']??null,'host'=>$mailer['host']??null,'port'=>$mailer['port']??null,'encryption'=>$mailer['encryption']??($mailer['scheme']??null),'timeout'=>$mailer['timeout']??null,
            'usernameSha'=>hash('sha256',(string)($mailer['username']??'')),'passwordSha'=>hash('sha256',(string)($mailer['password']??'')),'from'=>$mail['from']??null,'mailers'=>array_keys((array)($mail['mailers']??[]))],JSON_THROW_ON_ERROR),(string)$key);
        echo json_encode(['ok'=>true,'extensions'=>$ext,'phpVersionOk'=>PHP_VERSION_ID>=80401&&PHP_VERSION_ID<80500,'appUrlHttpsOrigin'=>$origin,'mailTransportKind'=>is_string($mailer['transport']??null)?$mailer['transport']:'UNKNOWN','mailFingerprintHMAC'=>$fingerprint],JSON_THROW_ON_ERROR).PHP_EOL;exit(0);
    }
    if($mode==='media-sample'){
        // B1150_FILL: return ['path'=>'/media/p/<image>/<rendition>','query'=>['v'=>'<version>','s'=>'<signature>']] for the first product image
        // using the application's own URL signer (the same call the catalog view makes), or null when there is no product image.
        // Read-only: no INSERT/UPDATE, no cache write that matters. Until the code is known the hook reports no sample.
        $sample=null;
        echo json_encode(['ok'=>true,'sample'=>$sample,'hook'=>'NOT_FILLED_IN'],JSON_THROW_ON_ERROR).PHP_EOL;exit(0);
    }
    $loaded=0;foreach(NEW_CLASSES as $c)if(class_exists($c,true))$loaded++;
    $b1149Loaded=0;foreach(B1149_CLASSES as $c)if(class_exists($c,true))$b1149Loaded++;
    $apis=true;foreach(CHANGED_APIS as [$class,$method])if(!class_exists($class,true)||!method_exists($class,$method))$apis=false;
    $routes=$app->make('router')->getRoutes();$routes->refreshNameLookups();
    $site=$routes->getByName('site-assets.show');$smtp=$routes->getByName('admin.settings.smtp.index');$theme=$routes->getByName('public-shop.theme');$media=$routes->getByName(MEDIA_ROUTE_NAME);
    $themeMethods=$theme===null?[]:array_values(array_diff($theme->methods(),['HEAD']));
    echo json_encode(['ok'=>true,'newClassesTotal'=>count(NEW_CLASSES),'newClassesLoaded'=>$loaded,'newClassesAutoloaded'=>count(NEW_CLASSES)>0&&$loaded===count(NEW_CLASSES),'changedStaticApis'=>$apis,'routeMedia'=>$media!==null&&in_array('GET',$media->methods(),true),
        'b1149ClassesLoaded'=>$b1149Loaded===count(B1149_CLASSES),'routeSiteAssets'=>$site!==null&&in_array('GET',$site->methods(),true),'routeSmtpIndex'=>$smtp!==null&&in_array('GET',$smtp->methods(),true),
        'providerRegistered'=>array_key_exists('App\Providers\MailSettingsServiceProvider',$app->getLoadedProviders()),'themeRoutePostOnly'=>$themeMethods===['POST'],'routesCached'=>$app->routesAreCached()],JSON_THROW_ON_ERROR).PHP_EOL;exit(0);
}catch(Throwable){$fail('APP_CHECK_BOOT_OR_CLASS_UNAVAILABLE');}
